60:+	 * @param tickDuration
61:+	 *            The duration of a tick in
62:+	 *            <code>milliseconds * {@link TickHandler#getDeltaMultiplier()}</code>.
63:+	 */
64:+	public TickCounter(TickHandler tickHandler, int maxTicks,
65:+			int tickDuration) {
66:+		this.tickHandler = tickHandler;
67:+		this.maxTicks = maxTicks;
68:+		this.tickDuration = tickDuration;
69:+
70:+		tickCount = maxTicks;
71:+	}
72:+
73:+	/**
74:+	 * Updates the tick counter. Whenever a tick is over,
75:+	 * {@link TickHandler#onTick()} is called on the tick handler.
76:+	 * 
77:+	 * @return Returns <code>true</code> <i>once<i>, when the max tick count is
78:+	 *         reached. After that {@link #reset()} has to be called.
79:+	 */
80:+	public boolean update() {
81:+		if (lastTime == -1)
82:+			lastTime = System.currentTimeMillis();
83:+
84:+		// Zeit-Delta ermitteln
85:+		long currentTime = System.currentTimeMillis();
86:+		long delta = (currentTime - lastTime)
87:+				* tickHandler.getDeltaMultiplier();
88:+		lastTime = currentTime;
89:+
90:+		updateTime += delta;
91:+
92:+		// Ticks berechnen
93:+		while (updateTime >= tickDuration && tickCount < maxTicks) {
94:+			// Neuer Update Tick
95:+			updateTime -= tickDuration;
96:+			tickCount++;
97:+			tickHandler.onTick();
98:+		}
99:+
100:+		// true einmalig bei maxTicks zurückgeben
101:+		if (tickCount == maxTicks) {
102:+			if (!finished) {
103:+				finished = true;
